<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use App\Models\Company;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class CompanyProfileController extends Controller{public function show(Request $request):JsonResponse{$company=$this->company($request);return response()->json(['data'=>$this->payload($company)]);}public function update(Request $request):JsonResponse{$company=$this->company($request);$data=$request->validate(['name'=>['required','string','max:150'],'legal_name'=>['nullable','string','max:180'],'tax_id'=>['nullable','string','max:30',Rule::unique('companies','tax_id')->ignore($company->id)],'description'=>['nullable','string','max:3000'],'industry'=>['nullable','string','max:120'],'location'=>['nullable','string','max:150'],'website'=>['nullable','url','max:255'],'phone'=>['nullable','string','max:30'],'size'=>['nullable',Rule::in(['1-10','11-50','51-200','201-500','501+'])]],['website.url'=>'El sitio web debe ser una URL completa, por ejemplo: https://empresa.com.']);if($company->verification_status==='pending')$data['verification_status']='incomplete';$company->update($data);return response()->json(['data'=>$this->payload($company->fresh()),'message'=>'Perfil empresarial actualizado.']);}public function submit(Request $request):JsonResponse{$company=$this->company($request);$required=['name','legal_name','tax_id','description','industry','location','phone','size'];$missing=collect($required)->filter(fn($field)=>blank($company->{$field}))->values();if($missing->isNotEmpty())return response()->json(['message'=>'Completa los datos obligatorios antes de solicitar verificación.','errors'=>['profile'=>['Faltan: '.$missing->join(', ')]]],422);$company->update(['verification_status'=>'pending','verification_submitted_at'=>now()]);return response()->json(['data'=>$this->payload($company->fresh()),'message'=>'Solicitud de verificación enviada.']);}private function company(Request $request):Company{abort_unless($request->user()->account_type==='company',403,'Esta función es exclusiva para empresas y representantes.');$company=$request->user()->companies()->wherePivot('status','active')->first();if($company)return $company;$base=$request->user()->name?:'Empresa';$slug=Str::slug($base).'-'.$request->user()->id;$company=Company::create(['name'=>$base,'slug'=>$slug,'status'=>'active','verification_status'=>'incomplete']);$company->members()->attach($request->user()->id,['role'=>'owner','status'=>'active']);return $company;}private function payload(Company $company):array{$fields=['name','legal_name','tax_id','description','industry','location','phone','size'];$completed=collect($fields)->filter(fn($field)=>filled($company->{$field}))->count();return [...$company->toArray(),'completion'=>(int)round($completed/count($fields)*100),'member_role'=>$company->members()->first()?->pivot->role];}}
